package com.bank.intersection;

import java.util.*;
import java.util.logging.*;
import java.util.stream.IntStream;

public class LookupDemo {
    private static final Logger log = Logger.getLogger("Intersection");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> active = IntStream.range(0, 20).boxed().toList();
        List<Integer> flagged = List.of(3, 7, 11, 15);
        IntersectionService service = new IntersectionService();

        log.info(() -> "list::contains  (O(n*m)): " + service.slow(active, flagged));
        log.info(() -> "set::contains   (O(n))  : " + service.fast(active, flagged));
    }
}

// ─── Would be in service/IntersectionService.java ───
class IntersectionService {
    // SLOW: list::contains is O(m) each → O(n*m) overall
    List<Integer> slow(List<Integer> active, List<Integer> flagged) {
        return active.stream()
            .filter(flagged::contains)      // linear scan per element
            .toList();
    }

    // FAST: HashSet::contains is O(1) each → O(n) overall
    List<Integer> fast(List<Integer> active, List<Integer> flagged) {
        Set<Integer> flaggedSet = new HashSet<>(flagged);   // built once, O(m)
        return active.stream()
            .filter(flaggedSet::contains)   // O(1) lookup per element
            .toList();
    }
}
